public Map<String, Object> uploadConfig(String str, MultipartFile multipartFile) {
    if (str == null || str.isEmpty()) {
        return HttpResult.onError("serial required");
    }
    try {
        Module module = ModuleSupervisor.getIns().getModule(str);
        try {
            String serverIp = getServerIp(module);
            if (serverIp != null && !serverIp.isEmpty()) {
                return UploadService.saveFile(AppContext.context, multipartFile, "tgz", str + ".tgz", 104857600L, new UpdateUI(module, serverIp), ".tgz");
            }
            return HttpResult.onError("hotspotIp ip address is empty");
        } catch (Throwable th) {
            th.printStackTrace();
            return HttpResult.onError(th.getMessage());
        }
    } catch (Exception e) {
        e.printStackTrace();
        return HttpResult.onError(e.getMessage());
    }
}
